-- =====================================================================
-- CareDesk CRM | Remove autogenerated WhatsApp contacts & chats
-- =====================================================================

create or replace function cleanup_whatsapp_autogen() returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_interactions int := 0;
  v_cases int := 0;
  v_patients int := 0;
  v_events int := 0;
  v_pat_ids uuid[];
  v_case_ids uuid[];
begin
  if current_user = 'caredesk_app' and not is_service() and not has_role('admin', 'supervisor') then
    raise exception 'Not allowed for your role';
  end if;

  -- 1. Identify all cases created via WhatsApp
  select coalesce(array_agg(id), '{}') into v_case_ids
  from cases
  where source_channel = 'whatsapp';

  -- 2. Identify patients that were created by WhatsApp auto-sync and have no other legitimate cases/calls
  select coalesce(array_agg(p.id), '{}') into v_pat_ids
  from patients p
  where not exists (
    select 1 from cases c where c.patient_id = p.id and c.source_channel != 'whatsapp'
  )
  and not exists (
    select 1 from calls cl where cl.patient_id = p.id
  )
  and not exists (
    select 1 from interactions i where i.patient_id = p.id and i.channel != 'whatsapp'
  )
  and (
    exists (select 1 from cases c where c.patient_id = p.id and c.source_channel = 'whatsapp')
    or exists (select 1 from interactions i where i.patient_id = p.id and i.channel = 'whatsapp')
    or p.full_name = 'WhatsApp contact'
    or p.mobile not like '+91%'
  );

  -- 3. Delete WhatsApp interactions
  delete from interactions where channel = 'whatsapp';
  get diagnostics v_interactions = row_count;

  -- 4. Delete WhatsApp cases and their dependent records
  if v_case_ids is not null and array_length(v_case_ids, 1) > 0 then
    update calls set case_id = null where case_id = any(v_case_ids);
    update complaints set case_id = null where case_id = any(v_case_ids);
    update escalations set case_id = null where case_id = any(v_case_ids);
    update inbound_emails set case_id = null where case_id = any(v_case_ids);
    delete from interactions where case_id = any(v_case_ids);
    delete from approvals where case_id = any(v_case_ids);
    delete from sla_timers where case_id = any(v_case_ids);
    delete from case_items where case_id = any(v_case_ids);
    delete from case_stage_history where case_id = any(v_case_ids);
    delete from cases where id = any(v_case_ids);
    get diagnostics v_cases = row_count;
  end if;

  -- 5. Delete autogenerated patients
  if v_pat_ids is not null and array_length(v_pat_ids, 1) > 0 then
    update calls set patient_id = null where patient_id = any(v_pat_ids);
    update callbacks set patient_id = null where patient_id = any(v_pat_ids);
    update complaints set patient_id = null where patient_id = any(v_pat_ids);
    update inbound_emails set patient_id = null where patient_id = any(v_pat_ids);
    delete from cases where patient_id = any(v_pat_ids);
    delete from patients where id = any(v_pat_ids);
    get diagnostics v_patients = row_count;
  end if;

  -- 6. Delete WhatsApp bridge webhook events
  delete from webhook_events where source = 'whatsapp_qr' or event_id like 'waqr:%';
  get diagnostics v_events = row_count;

  -- 7. Reset integration settings
  update integration_settings
  set settings = jsonb_set(coalesce(settings, '{}'::jsonb), '{status}', '"disconnected"'::jsonb)
  where provider = 'whatsapp_qr';

  return jsonb_build_object(
    'interactions_deleted', v_interactions,
    'cases_deleted', v_cases,
    'patients_deleted', v_patients,
    'events_deleted', v_events
  );
end $$;

grant execute on function cleanup_whatsapp_autogen() to caredesk_app;

-- Run cleanup immediately upon migration deployment
select cleanup_whatsapp_autogen();

